const PlasmicDescendants = {
  root: [
    "root",
    "topNav",
    "brand",
    "navOverview",
    "navDataset",
    "navSexEstimation",
    "navEvaluation",
    "navProject",
    "courseInfo",
    "h1",
    "h2",
    "h3"
  ],
  topNav: [
    "topNav",
    "brand",
    "navOverview",
    "navDataset",
    "navSexEstimation",
    "navEvaluation",
    "navProject",
    "courseInfo"
  ],
  brand: ["brand"],
  navOverview: ["navOverview"],
  navDataset: ["navDataset"],
  navSexEstimation: ["navSexEstimation"],
  navEvaluation: ["navEvaluation"],
  navProject: ["navProject"],
  courseInfo: ["courseInfo"],
  h1: ["h1"],
  h2: ["h2"],
  h3: ["h3"]
} as const;
type NodeNameType = keyof typeof PlasmicDescendants;
type DescendantsType<T extends NodeNameType> =
  (typeof PlasmicDescendants)[T][number];
type NodeDefaultElementType = {
  root: "div";
  topNav: "div";
  brand: "div";
  navOverview: "a";
  navDataset: "a";
  navSexEstimation: "a";
  navEvaluation: "a";
  navProject: "a";
  courseInfo: "div";
  h1: "h1";
  h2: "h2";
  h3: "h3";
};

type ReservedPropsType = "variants" | "args" | "overrides";
type NodeOverridesType<T extends NodeNameType> = Pick<
  PlasmicResearchOverview__OverridesType,
  DescendantsType<T>
>;
type NodeComponentProps<T extends NodeNameType> =
  // Explicitly specify variants, args, and overrides as objects
  {
    variants?: PlasmicResearchOverview__VariantsArgs;
    args?: PlasmicResearchOverview__ArgsType;
    overrides?: NodeOverridesType<T>;
  } &
    // Specify variants directly as props
    Omit<PlasmicResearchOverview__VariantsArgs, ReservedPropsType> &
    // Specify args directly as props
    Omit<PlasmicResearchOverview__ArgsType, ReservedPropsType> &
    // Specify overrides for each element directly as props
    Omit<
      NodeOverridesType<T>,
      ReservedPropsType | VariantPropType | ArgPropType
    > &
    // Specify props for the root element
    Omit<
      Partial<React.ComponentProps<NodeDefaultElementType[T]>>,
      ReservedPropsType | VariantPropType | ArgPropType | DescendantsType<T>
    >;

function makeNodeComponent<NodeName extends NodeNameType>(nodeName: NodeName) {
  type PropsType = NodeComponentProps<NodeName> & { key?: React.Key };
  const func = function <T extends PropsType>(
    props: T & StrictProps<T, PropsType>
  ) {
    const { variants, args, overrides } = React.useMemo(
      () =>
        deriveRenderOpts(props, {
          name: nodeName,
          descendantNames: PlasmicDescendants[nodeName],
          internalArgPropNames: PlasmicResearchOverview__ArgProps,
          internalVariantPropNames: PlasmicResearchOverview__VariantProps
        }),
      [props, nodeName]
    );
    return PlasmicResearchOverview__RenderFunc({
      variants,
      args,
      overrides,
      forNode: nodeName
    });
  };
  if (nodeName === "root") {
    func.displayName = "PlasmicResearchOverview";
  } else {
    func.displayName = `PlasmicResearchOverview.${nodeName}`;
  }
  return func;
}

function withUsePlasmicAuth<P extends object>(
  WrappedComponent: React.ComponentType<P>
) {
  const WithUsePlasmicAuthComponent: React.FC<P> = props => {
    const dataSourceCtx = usePlasmicDataSourceContext() ?? {};
    const { isUserLoading, user, token } = plasmicAuth.usePlasmicAuth({
      appId: "i3VoAVnJX9276iNx9GeENM"
    });

    return (
      <PlasmicDataSourceContextProvider__
        value={{
          ...dataSourceCtx,
          isUserLoading,
          userAuthToken: token,
          user
        }}
      >
        <WrappedComponent {...props} />
      </PlasmicDataSourceContextProvider__>
    );
  };
  return WithUsePlasmicAuthComponent;
}

export const PlasmicResearchOverview = Object.assign(
  // Top-level PlasmicResearchOverview renders the root element
  withUsePlasmicAuth(makeNodeComponent("root")),
  {
    // Helper components rendering sub-elements
    topNav: makeNodeComponent("topNav"),
    brand: makeNodeComponent("brand"),
    navOverview: makeNodeComponent("navOverview"),
    navDataset: makeNodeComponent("navDataset"),
    navSexEstimation: makeNodeComponent("navSexEstimation"),
    navEvaluation: makeNodeComponent("navEvaluation"),
    navProject: makeNodeComponent("navProject"),
    courseInfo: makeNodeComponent("courseInfo"),
    h1: makeNodeComponent("h1"),
    h2: makeNodeComponent("h2"),
    h3: makeNodeComponent("h3"),

    // Metadata about props expected for PlasmicResearchOverview
    internalVariantProps: PlasmicResearchOverview__VariantProps,
    internalArgProps: PlasmicResearchOverview__ArgProps,

    pageMetadata: generateDynamicMetadata(wrapQueriesWithLoadingProxy({}), {
      pageRoute: "/research-overview",
      pagePath: "/research-overview",
      params: {},
      query: {}
    })
  }
);

export default PlasmicResearchOverview;
